def generate(seed):
    r = random.Random(seed)
    for _ in range(100):
        al = 'abcde'[:r.randint(4, 5)]
        a = ''.join(r.choice(al) for _ in range(r.randint(11, 16)))
        b = ''.join(r.choice(al) for _ in range(r.randint(11, 16)))
        prev = [0] * (len(b) + 1)
        for x in a:
            cur = [0]
            for j, y in enumerate(b):
                cur.append(prev[j] + 1 if x == y else max(prev[j + 1], cur[j]))
            prev = cur
        L = prev[-1]
        if L >= 4:
            return a + '|' + b + '|' + str(L)
    return a + '|' + b + '|' + str(L)

